part of 'user_cubit.dart';@immutableclass UserClassState {  final bool loading;  final String error;  final bool? errorUser ;  final bool? success;  final UserDataModel userDataModel;  const UserClassState({    required this.userDataModel,    this.loading = false,    this.error = '',    this.errorUser,    this.success,  });  UserClassState copyWith({    bool? loading,    String? message,    String? error,    bool? success,    bool? errorUser,    UserDataModel? userDataModel,  }) {    return UserClassState(      loading: loading ?? this.loading,      error: error ?? this.error,      errorUser: errorUser ?? this.errorUser,      success: success ?? this.success,      userDataModel: userDataModel ?? this.userDataModel,    );  }}